SELECT
    s.subject_name AS subjectName,
    SUM(t.duration) AS totalStudyTime,
    ROUND(
        CAST(SUM(t.duration) * 100.0 /
        NULLIF((
            SELECT SUM(duration)
            FROM timer
            WHERE member_id = #{memberId}
                AND timer_date BETWEEN #{startDate} AND #{endDate}
        ), 0) AS NUMERIC),
        1
    ) AS ratio
FROM timer t
INNER JOIN subject s ON t.subject_id = s.subject_id
WHERE t.member_id = #{memberId}
AND t.timer_date BETWEEN #{startDate} AND #{endDate}
GROUP BY s.subject_id, s.subject_name
ORDER BY totalStudyTime DESC

SELECT COALESCE(SUM(duration), 0)
FROM timer
WHERE member_id = #{memberId}
    AND timer_date = #{today}
